import{_ as a,o,c as s,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Segurança","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/security.md","filePath":"pt-BR/guide/security.md"}'),i={name:"pt-BR/guide/security.md"};function t(d,e,n,c,u,l){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="seguranca" tabindex="-1">Segurança <a class="header-anchor" href="#seguranca" aria-label="Permalink to &quot;Segurança&quot;">​</a></h1><ul><li><strong>Login:</strong> toda rota da API exige uma sessão ou um <a href="./api-tokens">token de API</a>, exceto criar o primeiro administrador, entrar e aceitar um convite. Tentativas com erro repetidas do mesmo endereço ficam bloqueadas por um tempo. As contas podem ter um <a href="./two-factor">segundo fator</a>, e o administrador pode exigir de todos.</li><li><strong>Papéis:</strong> toda operação confere o papel de quem chama no workspace que ela afeta, e listas e atualizações ao vivo só trazem os workspaces de que a pessoa participa. Veja <a href="./members">Membros e papéis</a>.</li><li><strong>O endereço do console:</strong> é publicado com um certificado do Let&#39;s Encrypt, e HTTP simples redireciona para HTTPS. O Orbit só responde pedidos que chegam pelo Traefik com um segredo que muda a cada vez que o Orbit inicia, e o firewall deixa a porta dele acessível só pelo servidor e pelos seus workloads.</li><li><strong>Agentes:</strong> precisam de um certificado de cliente da autoridade certificadora do próprio Orbit que não esteja revogado nem expirado.</li><li><strong>Servidores adicionados:</strong> as chaves SSH deles são fixadas quando você confirma a impressão digital, e toda conexão seguinte recusa uma chave diferente. Chaves privadas coladas ficam só na memória.</li><li><strong>Segredos guardados:</strong> variáveis marcadas como secretas, senhas de bancos, a chave do App do GitHub e os tokens do GitLab e do Bitbucket são seladas com AES-256-GCM, com uma chave mantida fora do banco do Orbit. Senhas de usuários usam Argon2id, e tokens de sessão, de registro e de API ficam guardados só como hash. O diretório de dados do Orbit só pode ser lido pelo root.</li><li><strong>Logs:</strong> segredos e padrões comuns de credenciais são removidos antes de qualquer coisa ser guardada. Veja <a href="./operating#redaction">Operando o Orbit</a>.</li><li><strong>Terminais:</strong> um shell numa instância ou num banco exige um membro logado com o papel, nunca um token de API. A atividade registra quem abriu e fechou qual instância; teclas e saída nunca são gravadas. Veja <a href="./applications#terminal">Aplicações</a>.</li><li><strong>Versões:</strong> toda versão é assinada. O console se recusa a atualizar para uma versão cuja assinatura não bate com a chave fixada no Orbit em execução.</li><li><strong>Previews de pull request:</strong> pull requests de forks nunca rodam nos seus servidores.</li></ul>',2)])])}const g=a(i,[["render",t]]);export{p as __pageData,g as default};
